let loaded = null

/** @returns {Promise<Uint8Array>} the dictionary, inflated once and kept */
export function loadBrotliDictionary () {
  if (!loaded) {
    loaded = (async () => {
      const packed = Uint8Array.from(atob(DEFLATED), (c) => c.charCodeAt(0))
      const stream = new Blob([packed]).stream().pipeThrough(new DecompressionStream('deflate-raw'))
      return new Uint8Array(await new Response(stream).arrayBuffer())
    })()
  }
  return loaded
}

export default loadBrotliDictionary
